def next_palindrome(n):
    # Function to check if a number is palindrome
    def is_palindrome(num):
        return str(num) == str(num)[::-1]

    # If the number is already a palindrome, return the next one
    if is_palindrome(n):
        return next_palindrome(n + 1)

    # Start searching from the middle of the number
    mid = len(str(n)) // 2

    # Try adding digits to the left side of the middle digits
    for i in range(10 ** (mid - 1), 10 ** mid):
        # Construct the left and right sides of the palindrome
        left = str(i)
        right = str(i)[::-1][1:] if i > 1 else ''

        # Check if the constructed number is greater than n
        if int(left + right) > n:
            # If so, add a leading zero and check again
            left = '0' + left
            if int(left + right) <= n:
                # If the constructed number is now less than or equal to n,
                # return it
                return int(left + right)

        # If the constructed number is less than or equal to n,
        # return it
        if int(left + right) <= n:
            return int(left + right)

    # If no palindrome was found, return the smallest palindrome greater than n
    return 10 * int(str(n)[1:]) + int(str(n)[0])
```

